<script setup lang="ts">
import {ref,onMounted} from 'vue';import {api,errorMessage} from '../api';import {useAuth} from '../stores/auth';import PageHeader from '../components/PageHeader.vue';
const auth=useAuth(),data=ref<any>(null),error=ref('');async function load(){try{data.value=await api('/dashboard');error.value='';}catch(e){error.value=errorMessage(e);}}onMounted(load);
</script>
<template><PageHeader title="Dashboard" description="Resumen de la operación comercial" /><p v-if="error" class="notice error" role="alert">{{error}} <button class="text-button" @click="load">Reintentar</button></p><div v-if="data" class="metrics"><article class="card"><small>Clientes activos</small><strong>{{data.clients}}</strong></article><article class="card"><small>Pedidos registrados</small><strong>{{data.orders}}</strong></article><article class="card"><small>Pendientes de validación</small><strong>{{data.pending}}</strong></article><article class="card"><small>Visitas programadas</small><strong>{{data.scheduled}}</strong></article></div><section class="card"><h2>Tu operación</h2><p class="muted">{{auth.isAdmin?'Gestiona tu equipo, planifica las visitas y valida los pedidos antes de preparación.':auth.canSell?'Revisa tus visitas y registra los pedidos de tus clientes asignados.':'Consulta el estado de los pedidos y el seguimiento comercial.'}}</p><div class="actions"><RouterLink class="button" to="/pedidos">Ver pedidos</RouterLink><RouterLink class="button secondary" to="/rutas">Rutas y visitas</RouterLink><RouterLink class="button secondary" to="/clientes">Directorio de clientes</RouterLink></div></section></template>
